package com.nook.widgets;

import android.app.PendingIntent;
import android.content.*;
import android.appwidget.AppWidgetManager;
import android.net.Uri;
import android.view.View;
import android.widget.RemoteViews;
import org.json.JSONObject;
import java.util.*;

/** At-a-glance/Quick Look composition with native time and optional real data. */
public final class QuickLookWidget {
    private QuickLookWidget(){}
    public static RemoteViews render(Context c,int id,JSONObject config,boolean small,boolean preview){boolean compact=small||config.optInt("density",0)==1;RemoteViews v=new RemoteViews(c.getPackageName(),WidgetDesign.layout(c,"widget_tools"+(compact?"_compact":""),config));WidgetDesign.Colors colors=WidgetDesign.colors(config,"clock");for(int view:new int[]{R.id.widget_meta,R.id.widget_actions,R.id.widget_progress,R.id.widget_row0,R.id.widget_row1,R.id.widget_row2,R.id.tool_visual,R.id.tool_clocks,R.id.extra_chrono})v.setViewVisibility(view,View.GONE);v.setImageViewResource(R.id.widget_surface,Widgets.surfaceResource(config,"clock"));v.setImageViewResource(R.id.widget_icon,R.drawable.ic_clock);for(int image:Widgets.BACKGROUND_IMAGES)v.setInt(image,"setImageAlpha",Widgets.surfaceAlpha(config));v.setTextViewText(R.id.widget_label,config.optString("title","Quick Look"));v.setViewVisibility(R.id.widget_time,View.VISIBLE);v.setViewVisibility(R.id.widget_date,View.VISIBLE);v.setCharSequence(R.id.widget_time,"setFormat12Hour",config.optInt("variant",0)==1?"HH:mm":"h:mm a");v.setCharSequence(R.id.widget_time,"setFormat24Hour",config.optInt("variant",0)==1?"HH:mm":"h:mm a");JSONObject data=WeatherData.cached(c,config),current=data.optJSONObject("current");v.setTextViewText(R.id.widget_title,current==null?"Choose a weather city":WeatherData.degrees(current.optDouble("temperature_2m"),config)+" · "+config.optString("city"));v.setTextViewText(R.id.widget_body,current==null?"Optional city weather and calendar access.":(WeatherData.failed(c,config)||System.currentTimeMillis()-data.optLong("fetchedAt")>7200000?"Cached · ":"")+WeatherData.condition(current.optInt("weather_code",-1))+" · Open-Meteo");List<WidgetData.Event> events=WidgetData.events(c,System.currentTimeMillis(),System.currentTimeMillis()+86400000);if(!events.isEmpty()&&!compact){WidgetData.Event event=events.get(0);v.setViewVisibility(R.id.widget_row0,View.VISIBLE);v.setTextViewText(R.id.widget_row0,event.title+" · "+Widgets.when(event.begin));if(!preview)v.setOnClickPendingIntent(R.id.widget_row0,PendingIntent.getActivity(c,0,WidgetUtilityActivity.intent(c,"event",id,String.valueOf(event.id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}WidgetDesign.surfaces(c,v,id,"clock",config,compact,new int[]{R.id.widget_action_bg0,R.id.widget_action_bg1,R.id.widget_action_bg2});WidgetDesign.dedicated(c,v,id,"quicklook",config,compact);for(int text:new int[]{R.id.widget_time,R.id.widget_title,R.id.widget_date,R.id.widget_row0})v.setTextColor(text,colors.text);v.setTextColor(R.id.widget_body,colors.muted);v.setTextViewTextSize(R.id.widget_time,android.util.TypedValue.COMPLEX_UNIT_SP,(compact?30:42)*WidgetDesign.scale(config));v.setTextViewTextSize(R.id.widget_title,android.util.TypedValue.COMPLEX_UNIT_SP,17*WidgetDesign.scale(config));if(!preview){PendingIntent setup=LibraryWidgets.configure(c,id,"clock");v.setOnClickPendingIntent(R.id.widget_settings,setup);v.setOnClickPendingIntent(R.id.widget_root,setup);}return v;}
}
